"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { useLanguage } from "@/components/i18n/LanguageProvider";

export default function MenuDropdown() {
  const pathname = usePathname();
  const { dictionary } = useLanguage();
  const [open, setOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState<{ top: number; left: number; width: number }>({
    top: 74,
    left: 12,
    width: 360,
  });
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const panelRef = useRef<HTMLElement | null>(null);

  function closeMenu() {
    setOpen(false);
  }

  function updateMenuPosition() {
    if (!buttonRef.current || typeof window === "undefined") return;
    const rect = buttonRef.current.getBoundingClientRect();
    const margin = 12;
    const width = Math.min(360, Math.max(280, window.innerWidth - margin * 2));
    const left = Math.min(Math.max(margin, rect.left), window.innerWidth - width - margin);
    const estimatedHeight = Math.min(window.innerHeight - margin * 2, 680);
    const openBelow = rect.bottom + 10 + estimatedHeight <= window.innerHeight - margin;
    const top = openBelow
      ? rect.bottom + 10
      : Math.max(margin, rect.top - estimatedHeight - 10);

    setMenuPosition({ top, left, width });
  }

  const menuLinks = useMemo(
    () => [
      { href: "/", label: dictionary.nav.home },
      { href: "/route-planner", label: dictionary.nav.planMyTrip },
      { href: "/restaurants", label: dictionary.nav.whereToEat },
      { href: "/shopping", label: dictionary.nav.shopping },
      { href: "/nightlife", label: dictionary.nav.nightlife },
      { href: "/culture", label: dictionary.nav.culture },
      { href: "/viewpoints", label: dictionary.nav.rooftops },
      { href: "/fourth-of-july", label: dictionary.nav.fourthOfJuly },
      { href: "/esim-usa", label: dictionary.nav.esim },
      { href: "/onboarding", label: dictionary.nav.editProfile, profileAction: true },
    ],
    [dictionary],
  );

  useEffect(() => {
    closeMenu();
  }, [pathname]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeMenu();
    };

    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
    };
  }, []);

  useEffect(() => {
    if (!open) return;
    updateMenuPosition();

    const onViewportChange = () => updateMenuPosition();
    window.addEventListener("resize", onViewportChange);
    window.addEventListener("scroll", onViewportChange, true);

    return () => {
      window.removeEventListener("resize", onViewportChange);
      window.removeEventListener("scroll", onViewportChange, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;

    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (panelRef.current?.contains(target) || buttonRef.current?.contains(target)) return;
      closeMenu();
    };

    document.addEventListener("mousedown", onPointerDown);
    return () => document.removeEventListener("mousedown", onPointerDown);
  }, [open]);

  return (
    <>
      <button
        ref={buttonRef}
        type="button"
        onClick={() => {
          if (!open) updateMenuPosition();
          setOpen((prev) => !prev);
        }}
        className="nyc-action px-4 py-2 text-sm"
        aria-expanded={open}
        aria-controls="main-navigation-drawer"
      >
        {dictionary.nav.menu}
      </button>

      {open ? (
        <>
          <div className="fixed inset-0 z-[5100] bg-slate-950/12 backdrop-blur-[2px]" aria-hidden="true" />

          <div id="main-navigation-drawer" className="fixed inset-0 z-[5200] pointer-events-none">
            <aside
              ref={panelRef}
              className="pointer-events-auto fixed overflow-hidden rounded-[28px] border border-slate-950/70 bg-[linear-gradient(180deg,rgba(255,255,255,0.94),rgba(255,248,231,0.985))] shadow-[0_28px_80px_rgba(15,23,42,0.28)] backdrop-blur-xl animate-[menu-float-in_220ms_ease-out]"
              style={{
                top: `${menuPosition.top}px`,
                left: `${menuPosition.left}px`,
                width: `${menuPosition.width}px`,
                maxHeight: "min(680px, calc(100dvh - 24px))",
              }}
            >
              <div className="flex h-full flex-col">
                <div className="border-b border-stone-200 bg-[#0A2342] px-5 py-5 text-white">
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-[11px] font-black uppercase tracking-[0.18em] text-[#D4AF37]">{dictionary.common.appName}</p>
                      <p className="mt-1 font-american-diner text-2xl">{dictionary.nav.menu}</p>
                    </div>
                    <button
                      type="button"
                      onClick={closeMenu}
                      className="flex h-9 w-9 items-center justify-center rounded-md border-2 border-white text-xl font-black shadow-[3px_3px_0_rgba(255,255,255,0.55)] hover:bg-white/10"
                      aria-label={dictionary.nav.closeMenu}
                    >
                      x
                    </button>
                  </div>
                </div>

                <nav className="flex-1 space-y-2 overflow-y-auto p-4">
                  {menuLinks.map((item) => (
                    <Link
                      key={item.href}
                      href={item.href}
                      prefetch
                      onClick={closeMenu}
                      className={`block rounded-2xl px-4 py-3 text-base transition hover:-translate-y-0.5 ${
                        item.profileAction
                          ? "nyc-flag-action mt-5"
                          : "nyc-smooth-card border border-slate-950/80 bg-white/88 font-black text-slate-800 shadow-[0_10px_24px_rgba(15,23,42,0.09)] hover:bg-[#fffdf4] hover:text-[#C1121F]"
                      }`}
                    >
                      {item.label}
                    </Link>
                  ))}
                </nav>

                <div className="border-t border-stone-200 p-4 text-xs font-semibold leading-5 text-slate-500">
                  {dictionary.nav.drawerNote}
                </div>
              </div>
            </aside>
          </div>
        </>
      ) : null}
    </>
  );
}
